sp_widget.client_script:
api.controller = function($scope, $timeout) {

    /* widget controller */

    var c = this;


    /* =====================================================
       INITIAL STATE
       ===================================================== */

    c.loading = false;

    c.savingResponse = false;

    c.searchText = '';

    c.typeFilter = '';

    c.statusFilter = '';

    c.selectedOpportunity = null;

    c.selectedResponse = '';


    /* =====================================================
       SIDEBAR
       ===================================================== */

    /*
     * TRUE:
     * Sidebar visible
     * Opportunities page moves/compresses right
     *
     * FALSE:
     * Sidebar hidden
     * Opportunities page expands back to full width
     */

    c.sidebarOpen = true;


    /* =====================================================
       TOGGLE SIDEBAR
       ===================================================== */

    c.toggleSidebar = function() {

        c.sidebarOpen =
            !c.sidebarOpen;

    };


    /* =====================================================
       CLOSE SIDEBAR
       ===================================================== */

    c.closeSidebar = function() {

        c.sidebarOpen = false;

    };


    /* =====================================================
       REFRESH
       ===================================================== */

    c.refresh = function() {

        c.loading = true;


        c.server.refresh().then(
            function(response) {

                c.loading = false;

            }
        ).catch(
            function() {

                c.loading = false;

                alert(
                    'Unable to refresh opportunities.'
                );

            }
        );

    };


    /* =====================================================
       FILTER OPPORTUNITIES
       ===================================================== */

    c.filteredOpportunities = function() {

        if (
            !c.data ||
            !c.data.opportunities
        ) {

            return [];

        }


        var search =
            (
                c.searchText ||
                ''
            )
            .toLowerCase()
            .trim();


        return c.data.opportunities.filter(
            function(opportunity) {


                /* SEARCH */

                if (search) {

                    var searchable = [

                        opportunity.opportunity_id,

                        opportunity.title,

                        opportunity.company,

                        opportunity.location,

                        opportunity.type,

                        opportunity.description

                    ]
                    .join(' ')
                    .toLowerCase();


                    if (
                        searchable.indexOf(
                            search
                        ) === -1
                    ) {

                        return false;

                    }

                }


                /* TYPE */

                if (
                    c.typeFilter &&
                    opportunity.type_value !==
                    c.typeFilter
                ) {

                    return false;

                }


                /* STATUS */

                if (
                    c.statusFilter &&
                    opportunity.status_value !==
                    c.statusFilter
                ) {

                    return false;

                }


                return true;

            }
        );

    };


    /* =====================================================
       CLEAR FILTERS
       ===================================================== */

    c.clearFilters = function() {

        c.searchText = '';

        c.typeFilter = '';

        c.statusFilter = '';

    };


    /* =====================================================
       COMPANY INITIAL
       ===================================================== */

    c.getCompanyInitial = function(
        opportunity
    ) {

        if (!opportunity) {

            return 'C';

        }


        var company =
            opportunity.company ||
            'Company';


        return company
            .substring(
                0,
                1
            )
            .toUpperCase();

    };


    /* =====================================================
       STATUS CLASS
       ===================================================== */

    c.getStatusClass = function(
        status
    ) {

        var value =
            (
                status ||
                ''
            )
            .toLowerCase();


        if (
            value === 'open'
        ) {

            return 'status-open';

        }


        if (
            value === 'closed'
        ) {

            return 'status-closed';

        }


        if (
            value === 'filled'
        ) {

            return 'status-filled';

        }


        return 'status-default';

    };


    /* =====================================================
       RESPONSE CLASS
       ===================================================== */

    c.getResponseClass = function(
        response
    ) {

        var value =
            (
                response ||
                ''
            )
            .toLowerCase();


        if (
            value === 'apply' ||
            value === 'applied'
        ) {

            return 'response-applied';

        }


        if (
            value === 'interested'
        ) {

            return 'response-interested';

        }


        if (
            value === 'not interested'
        ) {

            return 'response-not-interested';

        }


        if (
            value === 'ignored' ||
            value === 'pending'
        ) {

            return 'response-pending';

        }


        return 'response-empty';

    };


    /* =====================================================
       RESPONSE DOT
       ===================================================== */

    c.getResponseDotClass = function(
        response
    ) {

        return c.getResponseClass(
            response
        );

    };


    /* =====================================================
       VIEW APPLICATION
       ===================================================== */

    c.viewApplication = function(
        opportunity
    ) {

        if (!opportunity) {

            return;

        }


        c.selectedOpportunity =
            opportunity;


        c.selectedResponse =
            opportunity.response ||
            '';


        $timeout(
            function() {

                var modal =
                    document.querySelector(
                        '.application-modal'
                    );


                if (modal) {

                    modal.scrollTop = 0;

                }

            },
            50
        );

    };


    /* =====================================================
       CLOSE APPLICATION
       ===================================================== */

    c.closeApplication = function(
        event
    ) {

        if (
            event &&
            event.target !==
            event.currentTarget
        ) {

            return;

        }


        c.selectedOpportunity =
            null;


        c.selectedResponse =
            '';

    };


    /* =====================================================
       SAVE RESPONSE
       ===================================================== */


    /* =====================================================
       FILE SELECTION HANDLER FOR RESUME
       ===================================================== */
    c.onFileSelect = function(element) {
        if (!element.files || !element.files.length) {
            c.uploadedFileBase64 = null;
            c.selectedFileName = '';
            $scope.$apply();
            return;
        }
        var file = element.files[0];
        c.selectedFileName = file.name;
        var reader = new FileReader();
        reader.onload = function(e) {
            var result = e.target.result;
            c.uploadedFileBase64 = result.split(',')[1];
            c.uploadedFileName = file.name;
            c.uploadedFileType = file.type;
            $scope.$apply();
        };
        reader.readAsDataURL(file);
    };

    c.saveResponse = function() {

        if (
            !c.selectedOpportunity
        ) {

            return;

        }


        c.savingResponse =
            true;


        c.server.get({

            action:
                'save_response',

            opportunitySysId:
                c.selectedOpportunity.sys_id,

            response:
                c.selectedResponse,

            fileBase64:
                c.uploadedFileBase64,

            fileName:
                c.uploadedFileName,

            fileType:
                c.uploadedFileType

        }).then(
            function(response) {

                c.savingResponse =
                    false;


                if (
                    response &&
                    response.data &&
                    response.data.success
                ) {


                    /* UPDATE SELECTED */

                    c.selectedOpportunity.response = c.selectedResponse;

                    if (c.uploadedFileName) {
                        c.selectedOpportunity.resumeName = c.uploadedFileName;
                        if (response.data.attachedResumeSysId) {
                            c.selectedOpportunity.resumeSysId = response.data.attachedResumeSysId;
                        }
                    }

                    c.uploadedFileBase64 = null;
                    c.uploadedFileName = '';
                    c.selectedFileName = '';


                    /* UPDATE LIST */

                    c.data.opportunities.forEach(
                        function(opportunity) {

                            if (
                                opportunity.sys_id ===
                                c.selectedOpportunity.sys_id
                            ) {

                                opportunity.response = c.selectedResponse;
                                if (c.selectedOpportunity.resumeName) {
                                    opportunity.resumeName = c.selectedOpportunity.resumeName;
                                    opportunity.resumeSysId = c.selectedOpportunity.resumeSysId;
                                }

                            }

                        }
                    );


                    /* UPDATE KPI */

                    if (
                        response.data.stats &&
                        c.data.stats
                    ) {

                        c.data.stats =
                            response.data.stats;

                    }


                    /* UPDATE COUNTS */

                    if (
                        response.data.navCounts
                    ) {

                        c.data.navCounts =
                            response.data.navCounts;

                    }


                    alert(
                        response.data.message ||
                        'Response saved successfully.'
                    );


                } else {

                    alert(
                        response &&
                        response.data &&
                        response.data.message
                        ?
                        response.data.message
                        :
                        'Unable to save your response.'
                    );

                }

            }
        ).catch(
            function() {

                c.savingResponse =
                    false;


                alert(
                    'Unable to save your response.'
                );

            }
        );

    };


    /* =====================================================
       DASHBOARD
       ===================================================== */

    c.goToDashboard = function() {

        window.location.href =
            '?id=campus360_student_dashboard' +
            '&student=' +
            encodeURIComponent(
                c.data.studentId ||
                'STU_TEST_001'
            );

    };


    /* =====================================================
       CLEANUP
       ===================================================== */

    $scope.$on(
        '$destroy',
        function() {

            c.selectedOpportunity =
                null;

        }
    );

};

sp_widget.css:
/* =========================================================
   CAMPUS360 STUDENT OPPORTUNITIES
   ---------------------------------------------------------
   ONLY REQUESTED CHANGE:
   1. LEFT SIDEBAR = DEEP PURPLE
   2. TOP CAMPUS360 NAVBAR = WHITE
   3. SYSTEM ADMIN / SERVICENOW NAVBAR = HIDDEN
   4. FULL-LENGTH VIEW
   5. SCROLLBARS HIDDEN BUT SCROLLING STILL WORKS
   6. OPPORTUNITIES TOP CARD = DARK PURPLE
   ---------------------------------------------------------
   ALL CONTENT / DATA / NAVIGATION / MODALS PRESERVED
   ========================================================= */


/* =========================================================
   GLOBAL RESET
   ========================================================= */

html,
body {

  width: 100% !important;
  height: 100% !important;

  margin: 0 !important;
  padding: 0 !important;

  overflow: hidden !important;

}


/* =========================================================
   REMOVE SERVICENOW SYSTEM ADMINISTRATOR NAVBAR
   ========================================================= */

body:has(.campus360-opportunities) #sp-header,
body:has(.campus360-opportunities) header#sp-header,
body:has(.campus360-opportunities) .sp-header,
body:has(.campus360-opportunities) .sp-header-bar,
body:has(.campus360-opportunities) .sp-navbar,
body:has(.campus360-opportunities) #sp-nav,
body:has(.campus360-opportunities) #sp-nav-bar,
body:has(.campus360-opportunities) .sp-nav-bar,
body:has(.campus360-opportunities) .portal-header,
body:has(.campus360-opportunities) .portal-header-wrapper,
body:has(.campus360-opportunities) .service-portal-header,
body:has(.campus360-opportunities) .sp-page-header,
body:has(.campus360-opportunities) .sp-page-header-wrapper,
body:has(.campus360-opportunities) .header-wrapper,
body:has(.campus360-opportunities) header[role="banner"],
body:has(.campus360-opportunities) nav[role="navigation"],
body:has(.campus360-opportunities) .navbar,
body:has(.campus360-opportunities) .navbar-default,
body:has(.campus360-opportunities) .navbar-inverse,
body:has(.campus360-opportunities) nav.navbar {

  display: none !important;

  visibility: hidden !important;

  opacity: 0 !important;

  width: 0 !important;
  height: 0 !important;

  min-width: 0 !important;
  min-height: 0 !important;

  max-width: 0 !important;
  max-height: 0 !important;

  margin: 0 !important;
  padding: 0 !important;

  border: 0 !important;

  overflow: hidden !important;

}


/* =========================================================
   REMOVE SERVICENOW HEADER SPACE
   ========================================================= */

body:has(.campus360-opportunities) #sp-container,
body:has(.campus360-opportunities) #sp-page,
body:has(.campus360-opportunities) .sp-page,
body:has(.campus360-opportunities) .sp-container,
body:has(.campus360-opportunities) .page {

  margin-top: 0 !important;

  padding-top: 0 !important;

}


/* =========================================================
   SERVICENOW OUTER WRAPPERS
   ========================================================= */

body:has(.campus360-opportunities) .container,
body:has(.campus360-opportunities) .container-fluid,
body:has(.campus360-opportunities) .row,
body:has(.campus360-opportunities) [class*="col-"],
body:has(.campus360-opportunities) .well,
body:has(.campus360-opportunities) .panel {

  width: 100% !important;

  max-width: none !important;

  min-width: 0 !important;

  margin: 0 !important;

  padding-left: 0 !important;
  padding-right: 0 !important;

}


body:has(.campus360-opportunities) .panel-body {

  width: 100% !important;

  max-width: none !important;

  margin: 0 !important;

  padding: 0 !important;

}


/* =========================================================
   BODY
   ========================================================= */

body:has(.campus360-opportunities) {

  width: 100% !important;
  height: 100% !important;

  margin: 0 !important;
  padding: 0 !important;

  overflow: hidden !important;

  background: #f3f6fb !important;

}


/* =========================================================
   CAMPUS360 ROOT
   ========================================================= */

.campus360-opportunities {

  position: fixed !important;

  inset: 0 !important;

  width: 100vw !important;
  height: 100vh !important;

  min-width: 100vw !important;
  min-height: 100vh !important;

  max-width: 100vw !important;
  max-height: 100vh !important;

  margin: 0 !important;
  padding: 0 !important;

  display: block !important;

  overflow: hidden !important;

  background: #f3f6fb !important;

  color: #101828 !important;

  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Arial,
    sans-serif !important;

  -webkit-font-smoothing: antialiased !important;

  z-index: 999999 !important;

}


.campus360-opportunities *,
.campus360-opportunities *::before,
.campus360-opportunities *::after {

  box-sizing: border-box !important;

}


/* =========================================================
   SIDEBAR
   PURPLE ONLY
   ========================================================= */

.c360-sidebar {

  position: absolute !important;

  left: 0 !important;
  top: 0 !important;
  bottom: 0 !important;

  width: 285px !important;

  min-width: 285px !important;
  max-width: 285px !important;

  height: 100vh !important;

  min-height: 100vh !important;
  max-height: 100vh !important;

  z-index: 100 !important;

  display: flex !important;

  flex-direction: column !important;

  overflow: hidden !important;

  background:
    linear-gradient(
      180deg,
      #130d2f 0%,
      #160d38 48%,
      #100a29 100%
    ) !important;

  border-right:
    1px solid #2d2157 !important;

  color: #ffffff !important;

  box-shadow:
    4px 0 20px rgba(15,10,40,.18) !important;

  transition:
    transform .25s ease !important;

}


/* SIDEBAR CLOSED */

.campus360-opportunities.sidebar-closed
.c360-sidebar {

  transform:
    translateX(-105%) !important;

}


/* =========================================================
   SIDEBAR BRAND
   ========================================================= */

.c360-sidebar-brand {

  height: 88px !important;

  min-height: 88px !important;

  flex: 0 0 88px !important;

  padding:
    0 20px !important;

  display:
    flex !important;

  align-items:
    center !important;

  gap:
    12px !important;

  border-bottom:
    1px solid rgba(255,255,255,.08) !important;

  background:
    transparent !important;

}


.c360-brand-logo {

  width:
    48px !important;

  height:
    48px !important;

  min-width:
    48px !important;

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    center !important;

  border-radius:
    14px !important;

  background:
    linear-gradient(
      135deg,
      #7c3aed,
      #9333ea
    ) !important;

  color:
    #ffffff !important;

  font-size:
    23px !important;

  font-weight:
    900 !important;

  box-shadow:
    0 7px 18px rgba(124,58,237,.34) !important;

}


.c360-brand-name {

  min-width:
    0 !important;

}


.c360-brand-name strong {

  display:
    block !important;

  color:
    #ffffff !important;

  font-size:
    20px !important;

  line-height:
    1.05 !important;

  font-weight:
    900 !important;

}


.c360-brand-name span {

  display:
    block !important;

  margin-top:
    4px !important;

  color:
    #c4b5fd !important;

  font-size:
    11px !important;

  font-weight:
    800 !important;

}


/* =========================================================
   SIDEBAR PROFILE
   ========================================================= */

.c360-sidebar-profile {

  margin:
    18px 13px 10px !important;

  min-height:
    67px !important;

  padding:
    12px !important;

  flex:
    0 0 auto !important;

  display:
    flex !important;

  align-items:
    center !important;

  gap:
    10px !important;

  border-radius:
    14px !important;

  background:
    linear-gradient(
      145deg,
      #1f1448,
      #21154d
    ) !important;

  border:
    1px solid #3c2b69 !important;

  text-decoration:
    none !important;

  box-shadow:
    0 6px 18px rgba(0,0,0,.16) !important;

}


.c360-sidebar-profile:hover {

  border-color:
    #5b3ea2 !important;

  background:
    linear-gradient(
      145deg,
      #271957,
      #2b1c61
    ) !important;

  box-shadow:
    0 8px 20px rgba(124,58,237,.18) !important;

}


.c360-profile-avatar {

  width:
    43px !important;

  height:
    43px !important;

  min-width:
    43px !important;

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    center !important;

  border-radius:
    50% !important;

  background:
    linear-gradient(
      135deg,
      #8b5cf6,
      #7c3aed
    ) !important;

  color:
    #ffffff !important;

  font-size:
    11px !important;

  font-weight:
    900 !important;

  box-shadow:
    0 6px 16px rgba(124,58,237,.28) !important;

}


.c360-profile-details {

  min-width:
    0 !important;

  flex:
    1 !important;

}


.c360-profile-details strong {

  display:
    block !important;

  max-width:
    180px !important;

  overflow:
    hidden !important;

  white-space:
    nowrap !important;

  text-overflow:
    ellipsis !important;

  color:
    #ffffff !important;

  font-size:
    13px !important;

  font-weight:
    900 !important;

}


.c360-profile-details span {

  display:
    block !important;

  margin-top:
    3px !important;

  color:
    #b9add7 !important;

  font-size:
    10px !important;

  font-weight:
    600 !important;

}


.c360-profile-arrow {

  color:
    #aaa0c2 !important;

  font-size:
    21px !important;

}


/* =========================================================
   SIDEBAR NAVIGATION
   HIDDEN SCROLLBAR
   SCROLLING STILL WORKS
   ========================================================= */

.c360-sidebar-navigation {

  flex:
    1 1 auto !important;

  min-height:
    0 !important;

  padding:
    2px 8px 12px !important;

  overflow-y:
    auto !important;

  overflow-x:
    hidden !important;

  scrollbar-width:
    none !important;

  -ms-overflow-style:
    none !important;

}


.c360-sidebar-navigation::-webkit-scrollbar {

  width:
    0 !important;

  height:
    0 !important;

  display:
    none !important;

}


.c360-sidebar-navigation::-webkit-scrollbar-track {

  background:
    transparent !important;

}


.c360-sidebar-navigation::-webkit-scrollbar-thumb {

  background:
    transparent !important;

}


/* =========================================================
   NAV HEADINGS
   ========================================================= */

.c360-nav-heading {

  padding:
    17px 9px 8px !important;

  color:
    #9f94bd !important;

  font-size:
    10px !important;

  font-weight:
    900 !important;

  line-height:
    1 !important;

  letter-spacing:
    .11em !important;

}


/* =========================================================
   NAV LINKS
   ========================================================= */

.c360-nav-link {

  position:
    relative !important;

  width:
    100% !important;

  min-height:
    46px !important;

  margin:
    3px 0 !important;

  padding:
    9px 12px !important;

  display:
    flex !important;

  align-items:
    center !important;

  gap:
    12px !important;

  border:
    0 !important;

  border-radius:
    11px !important;

  background:
    transparent !important;

  color:
    #ddd8e8 !important;

  font-size:
    14px !important;

  font-weight:
    750 !important;

  text-decoration:
    none !important;

  transition:
    background .2s ease,
    color .2s ease,
    transform .2s ease !important;

}


.c360-nav-link:hover {

  color:
    #ffffff !important;

  background:
    rgba(124,58,237,.16) !important;

  transform:
    translateX(2px) !important;

}


.c360-nav-link.active {

  color:
    #ffffff !important;

  background:
    linear-gradient(
      90deg,
      #7c3aed 0%,
      #8b3ff2 100%
    ) !important;

  font-weight:
    900 !important;

  box-shadow:
    0 7px 18px rgba(124,58,237,.28) !important;

}


.c360-nav-link.active::before {

  content:
    "" !important;

  position:
    absolute !important;

  left:
    0 !important;

  top:
    8px !important;

  bottom:
    8px !important;

  width:
    4px !important;

  border-radius:
    0 4px 4px 0 !important;

  background:
    #c4b5fd !important;

}


.c360-nav-icon {

  width:
    24px !important;

  height:
    24px !important;

  min-width:
    24px !important;

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    center !important;

  color:
    #b8aecb !important;

}


.c360-nav-link:hover
.c360-nav-icon {

  color:
    #ffffff !important;

}


.c360-nav-link.active
.c360-nav-icon {

  color:
    #ffffff !important;

}


.c360-nav-icon svg {

  width:
    21px !important;

  height:
    21px !important;

  fill:
    none !important;

  stroke:
    currentColor !important;

  stroke-width:
    1.8 !important;

  stroke-linecap:
    round !important;

  stroke-linejoin:
    round !important;

}


.c360-nav-text {

  min-width:
    0 !important;

  flex:
    1 !important;

  white-space:
    nowrap !important;

}


.c360-nav-count {

  margin-left:
    auto !important;

  min-width:
    23px !important;

  height:
    23px !important;

  padding:
    0 6px !important;

  border-radius:
    50% !important;

  background:
    rgba(139,92,246,.30) !important;

  color:
    #ddd6fe !important;

  border:
    1px solid rgba(196,181,253,.08) !important;

  font-size:
    11px !important;

  font-weight:
    900 !important;

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    center !important;

}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.c360-sidebar-footer {

  flex:
    0 0 auto !important;

  padding:
    10px 12px 13px !important;

  border-top:
    1px solid rgba(255,255,255,.08) !important;

  background:
    #120c2d !important;

}


.c360-journey-mini {

  padding:
    12px !important;

  border-radius:
    12px !important;

  background:
    linear-gradient(
      145deg,
      #1e143f,
      #21164a
    ) !important;

  border:
