.status-default {

  background:
    #eef2f6 !important;

  color:
    #526476 !important;

  border:
    1px solid #d7e0e8 !important;

}


/* =========================================================
   OVERVIEW
   ========================================================= */

.overview-grid {

  display:
    grid !important;

  grid-template-columns:
    1fr 1fr !important;

  gap:
    8px !important;

  margin-top:
    14px !important;

}


.overview-item {

  min-height:
    53px !important;

  padding:
    9px !important;

  border:
    1px solid #e2e8f0 !important;

  border-radius:
    9px !important;

  background:
    #fafcff !important;

}


.overview-item span {

  display:
    block !important;

  color:
    #7a8899 !important;

  font-size:
    8px !important;

  font-weight:
    900 !important;

  letter-spacing:
    .7px !important;

}


.overview-item strong {

  display:
    block !important;

  margin-top:
    4px !important;

  color:
    #2d4057 !important;

  font-size:
    10px !important;

  font-weight:
    850 !important;

  line-height:
    1.3 !important;

}


/* =========================================================
   ELIGIBILITY
   ========================================================= */

.eligibility-mini {

  display:
    flex !important;

  align-items:
    flex-start !important;

  gap:
    8px !important;

  margin-top:
    11px !important;

  padding:
    10px !important;

  border-radius:
    9px !important;

}


.eligibility-mini.eligible {

  background:
    #effbf4 !important;

  border:
    1px solid #c5ead4 !important;

}


.eligibility-mini.not-eligible {

  background:
    #fff1f2 !important;

  border:
    1px solid #efc5ca !important;

}


.eligibility-mini-icon {

  flex:
    0 0 auto !important;

  font-size:
    14px !important;

  font-weight:
    900 !important;

}


.eligibility-mini.eligible
.eligibility-mini-icon {

  color:
    #087d4b !important;

}


.eligibility-mini.not-eligible
.eligibility-mini-icon {

  color:
    #b83b48 !important;

}


.eligibility-mini strong {

  display:
    block !important;

  color:
    #236c49 !important;

  font-size:
    10px !important;

  font-weight:
    900 !important;

}


.eligibility-mini.not-eligible
strong {

  color:
    #a13f4a !important;

}


.eligibility-mini small {

  display:
    block !important;

  margin-top:
    3px !important;

  color:
    #66788a !important;

  font-size:
    9px !important;

  line-height:
    1.4 !important;

}


/* =========================================================
   RESPONSE
   ========================================================= */

.card-response {

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    space-between !important;

  margin-top:
    11px !important;

  padding-top:
    10px !important;

  border-top:
    1px solid #edf1f5 !important;

}


.card-response span:first-child {

  display:
    block !important;

  color:
    #7a8899 !important;

  font-size:
    8px !important;

  font-weight:
    900 !important;

  letter-spacing:
    .8px !important;

}


.card-response strong {

  display:
    block !important;

  margin-top:
    3px !important;

  font-size:
    10px !important;

  font-weight:
    900 !important;

}


.response-applied {

  color:
    #00845a !important;

}


.response-interested {

  color:
    #6240c9 !important;

}


.response-not-interested {

  color:
    #bd303a !important;

}


.response-pending {

  color:
    #a45c00 !important;

}


.response-empty {

  color:
    #667085 !important;

}


.response-dot {

  width:
    8px !important;

  height:
    8px !important;

  border-radius:
    50% !important;

}


.response-dot.response-applied {

  background:
    #00845a !important;

}


.response-dot.response-interested {

  background:
    #6240c9 !important;

}


.response-dot.response-not-interested {

  background:
    #bd303a !important;

}


.response-dot.response-pending {

  background:
    #d89a20 !important;

}


.response-dot.response-empty {

  background:
    #9aa7b5 !important;

}


/* =========================================================
   CARD FOOTER
   ========================================================= */

.card-footer {

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    space-between !important;

  gap:
    8px !important;

  margin-top:
    12px !important;

  padding-top:
    11px !important;

  border-top:
    1px solid #edf1f5 !important;

}


.view-application {

  padding:
    0 !important;

  border:
    0 !important;

  background:
    transparent !important;

  color:
    #673cff !important;

  font-size:
    10px !important;

  font-weight:
    900 !important;

  cursor:
    pointer !important;

}


.managed-text {

  color:
    #8794a4 !important;

  font-size:
    8px !important;

}


/* =========================================================
   LOADING
   ========================================================= */

.loading-state {

  min-height:
    220px !important;

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    center !important;

  gap:
    10px !important;

  color:
    #673cff !important;

  font-size:
    12px !important;

  font-weight:
    800 !important;

}


.loading-spinner {

  width:
    22px !important;

  height:
    22px !important;

  border:
    3px solid #dfd8ff !important;

  border-top-color:
    #673cff !important;

  border-radius:
    50% !important;

  animation:
    c360OpportunitySpin .75s linear infinite !important;

}


@keyframes c360OpportunitySpin {

  to {

    transform:
      rotate(360deg);

  }

}


/* =========================================================
   EMPTY
   ========================================================= */

.empty-state {

  padding:
    55px 20px !important;

  text-align:
    center !important;

  border:
    1px dashed #d5dce6 !important;

  border-radius:
    14px !important;

  background:
    #ffffff !important;

}


.empty-icon {

  color:
    #673cff !important;

  font-size:
    30px !important;

}


.empty-state h3 {

  margin:
    10px 0 5px !important;

  color:
    #263b49 !important;

  font-size:
    17px !important;

  font-weight:
    900 !important;

}


.empty-state p {

  margin:
    0 0 16px !important;

  color:
    #748396 !important;

  font-size:
    11px !important;

}


/* =========================================================
   MODAL
   ========================================================= */

.application-modal-backdrop {

  position:
    fixed !important;

  inset:
    0 !important;

  z-index:
    1000000 !important;

  padding:
    25px !important;

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    center !important;

  background:
    rgba(16,24,40,.52) !important;

}


.application-modal {

  width:
    min(920px,100%) !important;

  max-height:
    90vh !important;

  overflow-y:
    auto !important;

  background:
    #ffffff !important;

  border-radius:
    17px !important;

  box-shadow:
    0 25px 70px rgba(16,24,40,.25) !important;

  scrollbar-width:
    none !important;

  -ms-overflow-style:
    none !important;

}


.application-modal::-webkit-scrollbar {

  width:
    0 !important;

  height:
    0 !important;

  display:
    none !important;

}


.modal-header {

  padding:
    21px 23px !important;

  display:
    flex !important;

  align-items:
    flex-start !important;

  justify-content:
    space-between !important;

  gap:
    15px !important;

  border-bottom:
    1px solid #e7ecf2 !important;

}


.modal-heading h2 {

  margin:
    5px 0 3px !important;

  color:
    #172a33 !important;

  font-size:
    23px !important;

  font-weight:
    900 !important;

}


.modal-heading p {

  margin:
    0 !important;

  color:
    #65768a !important;

  font-size:
    11px !important;

}


.modal-close {

  width:
    35px !important;

  height:
    35px !important;

  border:
    1px solid #dce3eb !important;

  border-radius:
    9px !important;

  background:
    #ffffff !important;

  color:
    #65768a !important;

  font-size:
    20px !important;

  cursor:
    pointer !important;

}


.modal-body {

  padding:
    22px 23px !important;

}


.modal-top-row {

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    space-between !important;

  gap:
    10px !important;

  margin-bottom:
    18px !important;

}


.modal-opportunity-id {

  color:
    #6336db !important;

  font-size:
    11px !important;

  font-weight:
    900 !important;

}


.detail-section {

  margin-top:
    18px !important;

}


.detail-section-title {

  margin-bottom:
    9px !important;

  color:
    #673cff !important;

  font-size:
    9px !important;

  font-weight:
    900 !important;

  letter-spacing:
    1.2px !important;

}


.detail-grid {

  display:
    grid !important;

  grid-template-columns:
    repeat(3,minmax(0,1fr)) !important;

  gap:
    9px !important;

}


.detail-item {

  min-width:
    0 !important;

  padding:
    11px !important;

  border:
    1px solid #e3e8ef !important;

  border-radius:
    9px !important;

  background:
    #fafcff !important;

}


.detail-item span {

  display:
    block !important;

  color:
    #7b8999 !important;

  font-size:
    8px !important;

  font-weight:
    900 !important;

}


.detail-item strong {

  display:
    block !important;

  margin-top:
    4px !important;

  color:
    #304258 !important;

  font-size:
    10px !important;

  font-weight:
    850 !important;

  word-break:
    break-word !important;

}


.eligibility-detail {

  display:
    flex !important;

  align-items:
    flex-start !important;

  gap:
    10px !important;

  padding:
    13px !important;

  border-radius:
    9px !important;

}


.eligible-detail {

  background:
    #edf9f4 !important;

  border:
    1px solid #c7e7d6 !important;

}


.not-eligible-detail {

  background:
    #fff1f2 !important;

  border:
    1px solid #ecc4ca !important;

}


.eligibility-check {

  font-size:
    17px !important;

  font-weight:
    900 !important;

}


.eligible-detail
.eligibility-check {

  color:
    #087d4b !important;

}


.not-eligible-detail
.eligibility-check {

  color:
    #b83b48 !important;

}


.eligibility-detail strong {

  color:
    #263b49 !important;

  font-size:
    11px !important;

  font-weight:
    900 !important;

}


.eligibility-detail p {

  margin:
    4px 0 0 !important;

  color:
    #65768a !important;

  font-size:
    9px !important;

  line-height:
    1.5 !important;

}


.text-detail,
.description-detail {

  padding:
    13px !important;

  border:
    1px solid #e2e7ee !important;

  border-radius:
    9px !important;

  background:
    #fafcff !important;

  color:
    #43576d !important;

  font-size:
    10px !important;

  line-height:
    1.6 !important;

}


.skills-list {

  display:
    flex !important;

  flex-wrap:
    wrap !important;

  gap:
    6px !important;

}


.skill-tag {

  padding:
    5px 8px !important;

  border:
    1px solid #d8cdf7 !important;

  border-radius:
    6px !important;

  background:
    #f3efff !important;

  color:
    #6336db !important;

  font-size:
    9px !important;

  font-weight:
    850 !important;

}


.skills-empty {

  color:
    #7d8b9a !important;

  font-size:
    10px !important;

}


.response-editor {

  margin-top:
    17px !important;

  padding-top:
    15px !important;

  border-top:
    1px solid #e9edf2 !important;

}


.response-editor label {

  display:
    block !important;

  margin-bottom:
    7px !important;

  color:
    #68788c !important;

  font-size:
    9px !important;

  font-weight:
    900 !important;

  letter-spacing:
    .8px !important;

}


.response-row {

  display:
    flex !important;

  gap:
    9px !important;

}


.response-row select {

  flex:
    1 !important;

  height:
    42px !important;

  padding:
    0 10px !important;

  border:
    1px solid #d8e0e9 !important;

  border-radius:
    9px !important;

  background:
    #ffffff !important;

  color:
    #263b49 !important;

  font-size:
    11px !important;

}


.save-response {

  height:
    42px !important;

  padding:
    0 16px !important;

  border:
    0 !important;

  border-radius:
    9px !important;

  background:
    #673cff !important;

  color:
    #ffffff !important;

  font-size:
    10px !important;

  font-weight:
    900 !important;

  cursor:
    pointer !important;

}


.save-response:hover {

  background:
    #5832cb !important;

}


.save-response:disabled {

  opacity:
    .6 !important;

  cursor:
    not-allowed !important;

}


.modal-footer {

  padding:
    14px 23px !important;

  display:
    flex !important;

  justify-content:
    flex-end !important;

  border-top:
    1px solid #e7ecf2 !important;

}


.close-modal-btn {

  height:
    38px !important;

  padding:
    0 16px !important;

  border:
    1px solid #d8e0e9 !important;

  border-radius:
    9px !important;

  background:
    #ffffff !important;

  color:
    #536476 !important;

  font-size:
    10px !important;

  font-weight:
    850 !important;

  cursor:
    pointer !important;

}


/* =========================================================
   FOCUS
   ========================================================= */

.campus360-opportunities
button:focus-visible,
.campus360-opportunities
a:focus-visible,
.campus360-opportunities
input:focus-visible,
.campus360-opportunities
select:focus-visible {

  outline:
    3px solid rgba(81,70,229,.18) !important;

  outline-offset:
    2px !important;

}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width:1250px) {

  .c360-sidebar {

    width:
      250px !important;

    min-width:
      250px !important;

    max-width:
      250px !important;

  }


  .c360-opportunities-content {

    left:
      250px !important;

  }


  .campus360-opportunities.sidebar-closed
  .c360-opportunities-content {

    left:
      0 !important;

  }


  .stats-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;

  }


  .opportunity-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;

  }

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width:900px) {

  .c360-sidebar {

    position:
      fixed !important;

    top:
      0 !important;

    left:
      0 !important;

    bottom:
      0 !important;

    width:
      285px !important;

    min-width:
      285px !important;

    max-width:
      285px !important;

    transform:
      translateX(-105%) !important;

    box-shadow:
      8px 0 28px rgba(15,10,40,.22) !important;

  }


  .campus360-opportunities.sidebar-open
  .c360-sidebar {

    transform:
      translateX(0) !important;

  }


  .c360-opportunities-content {

    left:
      0 !important;

    width:
      100% !important;

  }


  .c360-sidebar-overlay {

    position:
      fixed !important;

    inset:
      0 !important;

    z-index:
      90 !important;

    display:
      block !important;

    background:
      rgba(15,10,40,.38) !important;

  }


  .campus360-opportunities.sidebar-closed
  .c360-sidebar-overlay {

    display:
      none !important;

  }


  .c360-topbar {

    height:
      70px !important;

    min-height:
      70px !important;

    padding:
      0 14px !important;

  }


  .c360-top-search {

    width:
      min(330px,100%) !important;

  }


  .c360-opportunities-body {

    padding:
      18px 16px 35px !important;

  }


  .stats-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;

  }


  .opportunity-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;

  }


  .filter-panel {

    flex-wrap:
      wrap !important;

  }


  .search-wrapper {

    flex:
      1 1 100% !important;

  }

}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width:650px) {

  .c360-topbar {

    height:
      62px !important;

    min-height:
      62px !important;

    padding:
      0 11px !important;

  }


  .c360-topbar-heading {

    display:
      none !important;

  }


  .c360-top-search {

    flex:
      1 !important;

    width:
      auto !important;

    height:
      38px !important;

  }


  .c360-top-search input {

    font-size:
      9px !important;

  }


  .c360-top-icon {

    width:
      36px !important;

    height:
      36px !important;

    min-width:
      36px !important;

  }


  .c360-top-profile {

    padding-left:
      4px !important;

  }


  .c360-top-profile-info,
  .c360-profile-chevron {

    display:
      none !important;

  }


  .c360-top-avatar {

    width:
      36px !important;

    height:
      36px !important;

    min-width:
      36px !important;

  }


  .c360-opportunities-body {

    padding:
      14px 11px 30px !important;

  }


  .opportunities-header {

    min-height:
      145px !important;

    padding:
      21px !important;

    border-radius:
      15px !important;

    background:
      linear-gradient(
        135deg,
        #241044 0%,
        #32145b 52%,
        #45206d 100%
      ) !important;

  }


  .opportunities-header h1 {

    font-size:
      25px !important;

    color:
      #ffffff !important;

  }


  .opportunities-header p {

    font-size:
      11px !important;

    color:
      #e5dcf0 !important;

  }


  .stats-grid {

    grid-template-columns:
      1fr !important;

  }


  .opportunity-grid {

    grid-template-columns:
      1fr !important;

  }


  .filter-wrapper {

    width:
      100% !important;

    min-width:
      0 !important;

  }


  .clear-filter {

    width:
      100% !important;

  }


  .section-heading {

    align-items:
      flex-start !important;

    flex-direction:
      column !important;

    gap:
      7px !important;

  }


  .card-header {

    flex-wrap:
      wrap !important;

  }


  .status-pill {

    margin-left:
      auto !important;

  }


  .detail-grid {

    grid-template-columns:
      1fr !important;

  }


  .response-row {

    flex-direction:
      column !important;

  }


  .save-response {

    width:
      100% !important;

  }


  .application-modal-backdrop {

    padding:
      10px !important;

  }


  .modal-header,
  .modal-body,
  .modal-footer {

    padding-left:
      15px !important;

    padding-right:
      15px !important;

  }

}


/* =========================================================
   FINAL SAFETY
   ========================================================= */

/* No outer browser scrollbar */

html:has(.campus360-opportunities),
body:has(.campus360-opportunities) {

  overflow:
    hidden !important;

}


/* Main page can still scroll */

.c360-opportunities-content {

  overflow-y:
    auto !important;

  overflow-x:
    hidden !important;

  scrollbar-width:
    none !important;

  -ms-overflow-style:
    none !important;

}


.c360-opportunities-content::-webkit-scrollbar {

  width:
    0 !important;

  height:
    0 !important;

  display:
    none !important;

}


/* Sidebar can still scroll */

.c360-sidebar-navigation {

  overflow-y:
    auto !important;

  overflow-x:
    hidden !important;

  scrollbar-width:
    none !important;

  -ms-overflow-style:
    none !important;

}


.c360-sidebar-navigation::-webkit-scrollbar {

  width:
    0 !important;

  height:
    0 !important;

  display:
    none !important;

}


/* Keep Campus360 full screen */

.campus360-opportunities {

  margin-top:
    0 !important;

  margin-bottom:
    0 !important;

}


/* Keep content full length */

.c360-opportunities-content {

  margin-left:
    0 !important;

  margin-right:
    0 !important;

}


/* =========================================================
   FINAL NAVBAR / HERO SEPARATION
   ========================================================= */

/* White Campus360 navbar remains above the page */

.c360-topbar {

  position:
    sticky !important;

  top:
    0 !important;

  z-index:
    5000 !important;

  background:
    #ffffff !important;

}


/* Content starts below navbar */

.c360-opportunities-body {

  position:
    relative !important;

  z-index:
    1 !important;

  padding-top:
    24px !important;

}


/* Dark-purple Opportunities top card */

.opportunities-header {

  position:
    relative !important;

  z-index:
    1 !important;

  margin-top:
    0 !important;

  background:
    linear-gradient(
      135deg,
      #241044 0%,
      #32145b 52%,
      #45206d 100%
    ) !important;

  border-color:
    #5a357d !important;

  color:
    #ffffff !important;

}


/* Dark hero text */

.opportunities-header h1 {

  color:
    #ffffff !important;

}


.opportunities-header p {

  color:
    #e5dcf0 !important;

}


.opportunities-eyebrow {

  color:
    #dccbff !important;

}


.eyebrow-dot {

  background:
    #c4b5fd !important;

}


/* =========================================================
   RESPONSIVE HERO / NAVBAR SEPARATION
   ========================================================= */

@media (max-width:900px) {

  .c360-opportunities-body {

    padding-top:
      18px !important;

  }

}


@media (max-width:650px) {

  .c360-opportunities-body {

    padding-top:
      14px !important;

  }

}

/* =========================================================
   RESUME UPLOAD CARD STYLING
   ========================================================= */
.resume-upload-card {
  margin-top: 14px;
  padding: 14px 16px;
  background: #f8fafc;
  border: 1px dashed #c0a8f7;
  border-radius: 12px;
  transition: all 0.2s ease;
}

.resume-upload-card:hover {
  border-color: #7b3aec;
  background: #fcfaff;
}

.resume-field-label {
  display: block;
  font-size: 11px;
  font-weight: 800;
  color: #1e293b;
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.req-star {
  color: #ef4444;
  font-weight: 900;
}

.resume-input-element {
  display: block;
  width: 100%;
  padding: 8px 10px;
  font-size: 12px;
  color: #334155;
  background: #ffffff;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  cursor: pointer;
}

.file-status-box {
  margin-top: 8px;
  font-size: 12px;
  color: #1e293b;
}

.existing-attachment a {
  color: #7b3aec;
  font-weight: 700;
  text-decoration: none;
}

.existing-attachment a:hover {
  text-decoration: underline;
}

.empty-hint {
  color: #64748b;
  font-size: 11px;
}

sp_widget.script:
(function() {

    /* =====================================================
       INITIAL DATA
       ===================================================== */

    data.studentName = '';
    data.studentId = '';
    data.studentInitials = 'ST';

    data.opportunities = [];

    data.types = [];
    data.statuses = [];

    data.stats = {
        total: 0,
        open: 0,
        eligible: 0,
        myApplications: 0
    };

    data.navCounts = {
        applications: 0,
        interviews: 0,
        interventions: 0
    };

    data.success = true;
    data.message = '';


    /* =====================================================
       STUDENT ID
       ===================================================== */

    var studentId =
        $sp.getParameter('student') ||
        'STU_TEST_001';


    /* =====================================================
       STUDENT MASTER
       ===================================================== */

    var studentGR =
        new GlideRecord(
            'x_snc_campus360_student_master'
        );

    studentGR.addQuery(
        'student_id',
        studentId
    );

    studentGR.query();

    var studentSysId = '';

    if (studentGR.next()) {

        studentSysId =
            studentGR.getUniqueValue();

        data.studentId =
            studentGR.getValue('student_id') ||
            studentId;

        data.studentName =
            studentGR.getValue('student_name') ||
            studentGR.getDisplayValue('student_name') ||
            'Student';

        var studentName =
            data.studentName.trim();

        if (studentName) {

            var nameParts =
                studentName.split(/\s+/);

            data.studentInitials =
                nameParts[0]
                .substring(0, 1)
                .toUpperCase();

            if (nameParts.length > 1) {

                data.studentInitials +=
                    nameParts[
                        nameParts.length - 1
                    ]
                    .substring(0, 1)
                    .toUpperCase();

            }
        }

    } else {

        data.studentId =
            studentId;

        data.studentName =
            'Student';

        data.studentInitials =
            'ST';
    }


    /* =====================================================
       SAVE STUDENT RESPONSE
       ===================================================== */

    if (
        input &&
        input.action === 'save_response'
    ) {

        saveStudentResponse(
            input.opportunitySysId,
            input.response,
            studentSysId
        );

        /*
         * Reload everything after saving.
         * This makes sure the latest application status
         * and student response are returned to the client.
         */

        loadOpportunities(
            studentSysId
        );

        loadNavCounts(
            studentSysId
        );

        return;
    }


    /* =====================================================
       INITIAL LOAD
       ===================================================== */

    loadOpportunities(
        studentSysId
    );

    loadNavCounts(
        studentSysId
    );


    /* =====================================================
       NAVIGATION COUNTS
       ===================================================== */

    function loadNavCounts(
        studentSysId
    ) {

        if (!studentSysId) {
            return;
        }


        /* -------------------------------------------------
           APPLICATIONS
           ------------------------------------------------- */

        var applicationGR =
            new GlideRecord(
                'x_snc_campus360_student_application'
            );

        if (
            applicationGR.isValid()
        ) {

            applicationGR.addQuery(
                'student',
                studentSysId
            );

            applicationGR.query();

            data.navCounts.applications =
                applicationGR.getRowCount();
        }


        /* -------------------------------------------------
           INTERVIEWS
           ------------------------------------------------- */

        var interviewGR =
            new GlideRecord(
                'x_snc_campus360_mock_interview'
            );

        if (
            interviewGR.isValid()
        ) {

            interviewGR.addQuery(
                'student',
                studentSysId
            );

            interviewGR.query();

            data.navCounts.interviews =
                interviewGR.getRowCount();
        }


        /* -------------------------------------------------
           INTERVENTIONS
           ------------------------------------------------- */

        var interventionGR =
            new GlideRecord(
                'x_snc_campus360_placement_intervention'
            );

        if (
            interventionGR.isValid()
        ) {

            interventionGR.addQuery(
                'student',
                studentSysId
            );

            interventionGR.query();

            data.navCounts.interventions =
                interventionGR.getRowCount();
        }

    }


    /* =====================================================
       LOAD OPPORTUNITIES
       ===================================================== */

    function loadOpportunities(
        studentSysId
    ) {

        /*
         * Reset these because this function can be called
         * again after saving a response.
         */

        data.opportunities = [];
        data.types = [];
        data.statuses = [];

        data.stats = {
            total: 0,
            open: 0,
            eligible: 0,
            myApplications: 0
        };


        var opportunityGR =
            new GlideRecord(
                'x_snc_campus360_placement_opportunity'
            );

        opportunityGR.orderBy(
            'opportunity_title'
        );

        opportunityGR.query();


        var typeMap = {};
        var statusMap = {};

        var opportunities = [];


        while (
            opportunityGR.next()
        ) {

            var opportunity =
                buildOpportunity(
                    opportunityGR,
                    studentSysId
                );


            opportunities.push(
                opportunity
            );


            data.stats.total++;


            if (
                opportunity.status_value ===
                'open'
            ) {

                data.stats.open++;
            }


            if (
                opportunity.eligible
            ) {

                data.stats.eligible++;
            }


            if (
                opportunity.response
            ) {

                data.stats.myApplications++;
            }


            /* TYPE FILTER */

            if (
                opportunity.type_value &&
                !typeMap[
                    opportunity.type_value
                ]
            ) {

                typeMap[
                    opportunity.type_value
                ] = {

                    value:
                        opportunity.type_value,

                    label:
                        opportunity.type
                };
            }


            /* STATUS FILTER */

            if (
                opportunity.status_value &&
                !statusMap[
                    opportunity.status_value
                ]
            ) {

                statusMap[
                    opportunity.status_value
                ] = {

                    value:
                        opportunity.status_value,

                    label:
                        opportunity.status
                };
            }

        }


        data.opportunities =
            opportunities;


        for (
            var typeKey in typeMap
        ) {

            if (
                typeMap.hasOwnProperty(
                    typeKey
                )
            ) {

                data.types.push(
                    typeMap[typeKey]
                );
            }
        }


        for (
            var statusKey in statusMap
        ) {

            if (
                statusMap.hasOwnProperty(
                    statusKey
                )
            ) {

                data.statuses.push(
                    statusMap[statusKey]
                );
            }
        }

    }


    /* =====================================================
       BUILD OPPORTUNITY
       ===================================================== */

    function buildOpportunity(
        opportunityGR,
        studentSysId
    ) {

        var opportunity = {

            sys_id:
                opportunityGR.getUniqueValue(),

            opportunity_id:
                getValue(
                    opportunityGR,
                    'opportunity_id'
                ),

            title:
                getValue(
                    opportunityGR,
                    'opportunity_title'
                ),

            company:
                getDisplay(
                    opportunityGR,
                    'company'
                ),

            type:
                getDisplay(
                    opportunityGR,
                    'opportunity_type'
                ),

            type_value:
                getValue(
                    opportunityGR,
                    'opportunity_type'
                ),

            status:
                getDisplay(
                    opportunityGR,
                    'status'
                ),

            status_value:
                getValue(
                    opportunityGR,
                    'status'
                ),

            location:
                getValue(
                    opportunityGR,
                    'location'
                ),

            ctc:
                getValue(
                    opportunityGR,
                    'ctc_stipend'
                ),

            minimum_cgpa:
                getValue(
                    opportunityGR,
                    'minimum_cgpa'
                ),

            drive_date:
                formatDateTime(
                    opportunityGR,
                    'drive_date'
                ),

            deadline:
                formatDateTime(
                    opportunityGR,
                    'application_deadline'
                ),

            eligible_branches:
                getValue(
                    opportunityGR,
                    'eligible_branches'
                ),

            skills:
                splitSkills(
                    getValue(
                        opportunityGR,
                        'required_skills'
                    )
                ),

            description:
                getValue(
                    opportunityGR,
                    'job_description'
                ),

            eligible:
                false,

            eligibilityMessage:
                '',

            response:
                '',

            application_id:
                '',

            application_status:
                '',

            assessment_status:
                '',

            offer_status:
                '',

            resumeName:
                '',

            resumeSysId:
                ''
        };


        /* =================================================
           ELIGIBILITY
           ================================================= */

        opportunity.eligible =
            checkEligibility(
                opportunityGR,
                studentSysId,
                opportunity
            );


        if (
            opportunity.eligible
        ) {

            opportunity.eligibilityMessage =
                'You meet the CGPA and branch requirements.';

        } else {

            opportunity.eligibilityMessage =
                'This opportunity does not currently match your profile.';
        }


        /* =================================================
           APPLICATION
           ================================================= */

        if (
            studentSysId
        ) {

            var applicationGR =
                new GlideRecord(
                    'x_snc_campus360_student_application'
                );


            applicationGR.addQuery(
                'student',
                studentSysId
            );


            applicationGR.addQuery(
                'opportunity',
                opportunityGR.getUniqueValue()
            );


            applicationGR.orderByDesc(
                'sys_created_on'
            );


            applicationGR.setLimit(
                1
            );


            applicationGR.query();


            if (
                applicationGR.next()
            ) {

                opportunity.application_id =
                    getValue(
                        applicationGR,
                        'application_id'
                    );


                opportunity.response =
                    getDisplay(
                        applicationGR,
                        'student_response'
                    );


                opportunity.application_status =
                    getDisplay(
                        applicationGR,
                        'application_status'
                    );


                opportunity.assessment_status =
                    getDisplay(
                        applicationGR,
                        'assessment_status'
                    );


                opportunity.offer_status =
                    getDisplay(
                        applicationGR,
                        'offer_status'
                    );


                /* -----------------------------------------
                   RESUME ATTACHMENT
                   ----------------------------------------- */

                var resumeName = '';
                var resumeSysId = '';


                var appAttGR =
                    new GlideRecord(
                        'sys_attachment'
                    );

                appAttGR.addQuery(
                    'table_name',
                    'x_snc_campus360_student_application'
                );

                appAttGR.addQuery(
                    'table_sys_id',
                    applicationGR.getUniqueValue()
                );

                appAttGR.orderByDesc(
                    'sys_created_on'
                );

                appAttGR.setLimit(
                    1
                );

                appAttGR.query();


                if (
                    appAttGR.next()
                ) {

                    resumeName =
                        appAttGR.getValue(
                            'file_name'
                        );

                    resumeSysId =
                        appAttGR.getUniqueValue();
                }


                /* -----------------------------------------
                   FALLBACK TO STUDENT MASTER RESUME
                   ----------------------------------------- */

                if (
                    !resumeName &&
                    studentSysId
                ) {

                    var masterAttGR =
                        new GlideRecord(
                            'sys_attachment'
                        );

                    masterAttGR.addQuery(
                        'table_name',
                        'x_snc_campus360_student_master'
                    );

                    masterAttGR.addQuery(
                        'table_sys_id',
                        studentSysId
                    );

                    masterAttGR.orderByDesc(
                        'sys_created_on'
                    );

                    masterAttGR.setLimit(
                        1
                    );

                    masterAttGR.query();


                    if (
                        masterAttGR.next()
                    ) {

                        resumeName =
                            masterAttGR.getValue(
                                'file_name'
                            );

                        resumeSysId =
                            masterAttGR.getUniqueValue();
                    }
                }


                opportunity.resumeName =
                    resumeName;

                opportunity.resumeSysId =
                    resumeSysId;
            }

        }


        return opportunity;

    }


    /* =====================================================
       ELIGIBILITY
       ===================================================== */

    function checkEligibility(
        opportunityGR,
        studentSysId,
        opportunity
    ) {

        if (
            !studentSysId
        ) {

            return false;
        }


        var studentGR =
            new GlideRecord(
                'x_snc_campus360_student_master'
            );


        if (
            !studentGR.get(
                studentSysId
            )
        ) {

            return false;
        }


        /* -------------------------------------------------
           CGPA
           ------------------------------------------------- */

        var studentCGPA =
            parseFloat(
                studentGR.getValue(
                    'cgpa'
                )
            );


        var minimumCGPA =
            parseFloat(
                opportunity.minimum_cgpa
            );


        if (
            !isNaN(minimumCGPA) &&
            !isNaN(studentCGPA) &&
            studentCGPA < minimumCGPA
        ) {

            return false;
        }


        /* -------------------------------------------------
           BRANCH
           ------------------------------------------------- */

        var studentBranch =
            (
                studentGR.getDisplayValue(
                    'branch'
                ) ||
                studentGR.getValue(
                    'branch'
                ) ||
                ''
            )
            .toLowerCase()
            .trim();


        var eligibleBranches =
            (
                opportunity.eligible_branches ||
                ''
            )
            .toLowerCase();


        if (
            studentBranch &&
            eligibleBranches
        ) {

            var branchList =
                eligibleBranches.split(',');

            var branchMatch =
                false;


            for (
                var i = 0;
                i < branchList.length;
                i++
            ) {

                var branch =
                    branchList[i]
                    .trim();


                if (
                    branch &&
                    (
                        branch ===
                        studentBranch ||

                        studentBranch.indexOf(
                            branch
                        ) !== -1 ||

                        branch.indexOf(
                            studentBranch
                        ) !== -1
                    )
                ) {

                    branchMatch =
                        true;

                    break;
                }
            }


            if (
                !branchMatch
            ) {

                return false;
            }
        }


        return true;

    }


    /* =====================================================
       RESPONSE → APPLICATION STATUS MAPPING
       ===================================================== */

    function getApplicationStatus(
        response
    ) {

        if (!response) {
            return '';
        }


        var normalizedResponse =
            String(response)
            .trim()
            .toLowerCase();


        /*
         * Student dropdown selection
         *        ↓
         * student_response
         *        ↓
         * application_status
         */

        if (
            normalizedResponse ===
            'apply'
        ) {

            return 'Submitted';
        }


        if (
            normalizedResponse ===
            'not interested'
        ) {

            return 'Withdrawn';
        }


        if (
            normalizedResponse ===
            'ignored'
        ) {

            return 'Withdrawn';
        }


        if (
            normalizedResponse ===
            'pending'
        ) {

            return 'Pending';
        }


        /*
         * If another response is introduced later,
         * keep the existing value as fallback.
         */

        return response;

    }


    /* =====================================================
       SAVE STUDENT RESPONSE
       ===================================================== */

    function saveStudentResponse(
        opportunitySysId,
        response,
        studentSysId
    ) {

        data.success =
            false;


        data.message =
            '';


        /* -------------------------------------------------
           VALIDATION
           ------------------------------------------------- */

        if (
            !opportunitySysId ||
            !studentSysId
        ) {

            data.message =
                'Student or opportunity information is missing.';

            return;
        }


        if (
            !response
        ) {

            data.message =
                'Please select a response.';

            return;
        }


        /* -------------------------------------------------
           GET OPPORTUNITY
           ------------------------------------------------- */

        var opportunityGR =
            new GlideRecord(
                'x_snc_campus360_placement_opportunity'
            );


        if (
            !opportunityGR.get(
                opportunitySysId
            )
        ) {

            data.message =
                'The selected opportunity could not be found.';

            return;
        }


        /* -------------------------------------------------
           FIND EXISTING APPLICATION
           ------------------------------------------------- */

        var applicationGR =
            new GlideRecord(
                'x_snc_campus360_student_application'
            );


        applicationGR.addQuery(
            'student',
            studentSysId
        );


        applicationGR.addQuery(
            'opportunity',
            opportunitySysId
        );


        applicationGR.orderByDesc(
            'sys_created_on'
        );


        applicationGR.setLimit(
            1
        );


        applicationGR.query();


        var isNew =
            false;


        if (
            !applicationGR.next()
        ) {

            /*
             * No application exists.
             * Create a new application record.
             */

            applicationGR.initialize();

            isNew =
                true;


            applicationGR.setValue(
                'student',
                studentSysId
            );


            applicationGR.setValue(
                'opportunity',
                opportunitySysId
            );
        }


        /* =================================================
           IMPORTANT RESPONSE LOGIC
           ================================================= */

        /*
         * Whatever the student selects in the dropdown
         * is saved into student_response.
         */

        if (
            applicationGR.isValidField(
                'student_response'
            )
        ) {

            applicationGR.setValue(
                'student_response',
                response
            );
        }


        /*
         * Convert the student's response into the
         * corresponding application status.
         *
         * Apply         → Submitted
         * Not Interested→ Withdrawn
         * Ignored      → Withdrawn
         * Pending       → Pending
         */

        var applicationStatus =
            getApplicationStatus(
                response
            );


        if (
            applicationGR.isValidField(
                'application_status'
            ) &&
            applicationStatus
        ) {

            applicationGR.setValue(
                'application_status',
                applicationStatus
            );
        }


        /* =================================================
           SAVE RECORD
           ================================================= */

        var savedId =
            '';


        if (
            isNew
        ) {

            /*
             * NEW RECORD → INSERT
             */

            savedId =
                applicationGR.insert();

        } else {

            /*
             * EXISTING RECORD → UPDATE
             */

            savedId =
                applicationGR.update();
        }


        /* =================================================
           RESUME FILE ATTACHMENT
           ================================================= */

        if (
            input.fileBase64 &&
            input.fileName &&
            savedId
        ) {

            try {

                var sa =
                    new GlideSysAttachment();


                /* -----------------------------------------
                   REMOVE OLD APPLICATION RESUME
                   ----------------------------------------- */

                var oldAtt =
                    new GlideRecord(
                        'sys_attachment'
                    );


                oldAtt.addQuery(
                    'table_name',
                    'x_snc_campus360_student_application'
                );


                oldAtt.addQuery(
                    'table_sys_id',
                    savedId
                );


                oldAtt.query();


                while (
                    oldAtt.next()
                ) {

                    oldAtt.deleteRecord();
                }


                /* -----------------------------------------
                   ATTACH NEW RESUME TO APPLICATION
                   ----------------------------------------- */

                var attSysId =
                    '';


                if (
                    typeof sa.writeBase64 ===
                    'function'
                ) {

                    attSysId =
                        sa.writeBase64(
                            applicationGR,
                            input.fileName,
                            input.fileType ||
                                'application/pdf',
                            input.fileBase64
                        );

                } else {

                    var bytes =
                        GlideStringUtil.base64DecodeAsBytes(
                            input.fileBase64
                        );


                    attSysId =
                        sa.write(
                            applicationGR,
                            input.fileName,
                            input.fileType ||
                                'application/pdf',
                            bytes
                        );
                }


                data.attachedResumeSysId =
                    attSysId;


                /* -----------------------------------------
                   UPDATE STUDENT MASTER RESUME
                   ----------------------------------------- */

                var studentResumeGR =
                    new GlideRecord(
                        'x_snc_campus360_student_master'
                    );


                if (
                    studentResumeGR.get(
                        studentSysId
                    )
                ) {

                    var oldStudentAtt =
                        new GlideRecord(
                            'sys_attachment'
                        );


                    oldStudentAtt.addQuery(
                        'table_name',
                        'x_snc_campus360_student_master'
                    );


                    oldStudentAtt.addQuery(
                        'table_sys_id',
                        studentSysId
                    );


                    oldStudentAtt.query();


                    while (
                        oldStudentAtt.next()
                    ) {

                        oldStudentAtt.deleteRecord();
                    }


                    if (
                        typeof sa.writeBase64 ===
                        'function'
                    ) {

                        sa.writeBase64(
                            studentResumeGR,
                            input.fileName,
                            input.fileType ||
                                'application/pdf',
                            input.fileBase64
                        );

                    } else {

                        var bytesSt =
                            GlideStringUtil.base64DecodeAsBytes(
                                input.fileBase64
                            );


                        sa.write(
                            studentResumeGR,
                            input.fileName,
                            input.fileType ||
                                'application/pdf',
                            bytesSt
                        );
                    }
                }


            } catch (
                attError
            ) {

                gs.error(
                    'Campus360 Resume attachment processing error: ' +
                    attError
                );
            }
        }


        /* =================================================
           SAVE SUCCESS
           ================================================= */

        if (
            savedId
        ) {

            data.success =
                true;


            data.message =
                'Your response was saved successfully.';


            /*
             * Return the latest statistics.
             */

            data.stats =
                calculateStats(
                    studentSysId
                );


            /*
             * Return the actual saved values too.
             * Useful for the client script/UI.
             */

            data.savedResponse =
                response;


            data.savedApplicationStatus =
                applicationStatus;


            data.savedApplicationSysId =
                savedId;

        } else {

            data.message =
                'The response could not be saved.';
        }

    }


    /* =====================================================
       CALCULATE STATS
       ===================================================== */

    function calculateStats(
        studentSysId
    ) {

        var stats = {

            total: 0,

            open: 0,

            eligible: 0,

            myApplications: 0

        };


        var opportunityGR =
            new GlideRecord(
                'x_snc_campus360_placement_opportunity'
            );


        opportunityGR.query();


        while (
            opportunityGR.next()
        ) {

            stats.total++;


            var status =
                getValue(
                    opportunityGR,
                    'status'
                )
                .toLowerCase();


            if (
                status ===
                'open'
            ) {

                stats.open++;
            }


            var temp =
                buildOpportunity(
                    opportunityGR,
                    studentSysId
                );


            if (
                temp.eligible
            ) {

                stats.eligible++;
            }


            if (
                temp.response
            ) {

                stats.myApplications++;
            }

        }


        return stats;

    }


    /* =====================================================
       UTILITIES
       ===================================================== */

    function getValue(
        gr,
        field
    ) {

        if (
            !gr ||
            !gr.isValidField(
                field
            )
        ) {

            return '';
        }


        return (
            gr.getValue(
                field
            ) || ''
        );

    }


    function getDisplay(
        gr,
        field
    ) {

        if (
            !gr ||
            !gr.isValidField(
                field
            )
        ) {

            return '';
        }


        return (
            gr.getDisplayValue(
                field
            ) || ''
        );

    }


    function formatDateTime(
        gr,
        field
    ) {

        if (
            !gr ||
            !gr.isValidField(
                field
            )
        ) {

            return '';
        }


        var value =
            gr.getValue(
                field
            );


        if (
            !value
        ) {

            return '';
        }


        return (
            gr.getDisplayValue(
                field
            ) ||
            value
        );

    }


    function splitSkills(
        value
    ) {

        if (
            !value
        ) {

            return [];
        }


        var parts =
            value.split(',');


        var result =
            [];


        for (
            var i = 0;
            i < parts.length;
            i++
        ) {

            var skill =
                parts[i].trim();


            if (
                skill
            ) {

                result.push(
                    skill
                );
            }
        }


        return result;

    }

})();


